const catalogs = Object.fromEntries(localeCodes.map((code) => [code, {}])) as Record<LocaleCode, Record<string, string>>;
for (const row of rows) {
  const [key, ...translations] = row;
  localeCodes.forEach((code, index) => {
    catalogs[code][key] = translations[index] ?? translations[2] ?? translations[0] ?? key;
  });
}

function normalizeLocale(value?: string | null): LocaleCode | null {
  if (!value) return null;
  const normalized = value.replace("_", "-").toLowerCase();
  if (normalized === "zh-tw" || normalized === "zh-hk" || normalized === "zh-hant") return "zh-TW";
  if (normalized.startsWith("zh")) return "zh-CN";
  const direct = localeCodes.find((code) => code.toLowerCase() === normalized);
  if (direct) return direct;
  const base = normalized.split("-")[0];
  return localeCodes.find((code) => code.toLowerCase() === base) ?? null;
}

function initialLocale(): LocaleCode {
  if (typeof window === "undefined") return "zh-CN";
  const stored = normalizeLocale(window.localStorage.getItem("lingzhan.locale.v1"));
  if (stored) return stored;
  for (const candidate of window.navigator.languages ?? [window.navigator.language]) {
    const matched = normalizeLocale(candidate);
    if (matched) return matched;
  }
  return "zh-CN";
}

export const locale = writable<LocaleCode>(initialLocale());

export function setLocale(code: LocaleCode) {
  locale.set(code);
  if (typeof window !== "undefined") window.localStorage.setItem("lingzhan.locale.v1", code);
}

export function applyDocumentLocale(code: LocaleCode) {
  if (typeof document === "undefined") return;
  const option = localeOptions.find((item) => item.code === code) ?? localeOptions[0];
  document.documentElement.lang = code;
  document.documentElement.dir = option.dir;
}

export function tr(key: string, params: MessageParams = {}, code: LocaleCode = "zh-CN"): string {
  const template = catalogs[code][key] ?? catalogs.en[key] ?? catalogs["zh-CN"][key] ?? key;
  return template.replace(/\{(\w+)\}/g, (_, name: string) => String(params[name] ?? `{${name}}`));
}

export function formatLocaleNumber(value: number, code: LocaleCode): string {
  return new Intl.NumberFormat(code).format(value);
}

export function formatLocaleDateTime(value: string | number | Date, code: LocaleCode): string {
  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) return String(value);
  return new Intl.DateTimeFormat(code, { dateStyle: "medium", timeStyle: "short" }).format(date);
}

export function translationCoverage(): Record<LocaleCode, { total: number; translated: number }> {
  const total = rows.length;
  return Object.fromEntries(
    localeCodes.map((code) => [code, { total, translated: Object.keys(catalogs[code]).length }])
  ) as Record<LocaleCode, { total: number; translated: number }>;
}
